B=blocks  # (demo, r, c, out)
byd={}
for d,r,c,o in B: byd.setdefault(d,[]).append((r,c,o))
res=[]
for dr in range(-3,4):
  for dc in range(-3,4):
    ok=True
    for d,lst in byd.items():
        i=demos[d][0]; H=len(i);W=len(i[0])
        tl={(r,c) for r,c,_ in lst}
        for r,c,o in lst:
            rr,cc=r+dr,c+dc
            v = 0 if not(0<=rr<H-1 and 0<=cc<W-1) else (1 if (rr,cc) in tl else 0)
            pred = 8 if v else 2
            if pred!=o: ok=False;break
        if not ok: break
    if ok: res.append((dr,dc))
print('offset rules:',res)
# feature: min chebyshev gap to another block
for d,lst in sorted(byd.items()):
    for r,c,o in lst:
        gaps=[max(abs(r-r2),abs(c-c2)) for r2,c2,_ in lst if (r2,c2)!=(r,c)]
        print(d,(r,c),o,'mingap',min(gaps) if gaps else None)

