def transform(g):
    H=len(g);W=len(g[0]);o=[row[:] for row in g]
    seen=set();bl=[]
    for r in range(H-1):
        for c in range(W-1):
            if g[r][c]==2 and g[r][c]==g[r][c+1]==g[r+1][c]==g[r+1][c+1]==2 and (r,c) not in seen:
                bl.append((r,c));seen|={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
    for r,c in bl:
        if sum(1 for r2,c2 in bl if c2>c)%2==0:
            for dr in(0,1):
                for dc in(0,1): o[r+dr][c+dc]=8
    return o
